insert into public.cpl_memory_log (memory_id, actor, action, note, after)
select id, 'SkyDipper (S666)', 'create', 'S666 checkpoint (2026-11-16)', to_jsonb(m)
from public.cpl_memory m where m.slug in
  ('d-rcc-originals-predate-curriqunet-s666','d-mpc-reload-three-s666','d-honors-step2-applied-not-a-hold-s666','d-person-saved-never-returns-s666','p-prior-rescore-route-is-prior-plus-reconcile-s666','p-dependency-map-reads-committed-files-s666','sam-sql-prompt-is-app-level-2026-11-16')
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create');
select m.slug, m.status, length(m.summary) as summary_chars, count(l.id) filter (where l.action = 'create') as creates
from public.cpl_memory m left join public.cpl_memory_log l on l.memory_id = m.id
where m.slug in
  ('d-rcc-originals-predate-curriqunet-s666','d-mpc-reload-three-s666','d-honors-step2-applied-not-a-hold-s666','d-person-saved-never-returns-s666','p-prior-rescore-route-is-prior-plus-reconcile-s666','p-dependency-map-reads-committed-files-s666','sam-sql-prompt-is-app-level-2026-11-16')
group by m.slug, m.status, m.summary order by m.slug;
